package cz.halloween.core;
import java.lang.reflect.Method;import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.Map;import org.bukkit.Bukkit;import org.bukkit.ChatColor;import org.bukkit.Material;import org.bukkit.command.CommandSender;import org.bukkit.enchantments.Enchantment;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.event.inventory.InventoryDragEvent;import org.bukkit.inventory.Inventory;import org.bukkit.inventory.InventoryHolder;import org.bukkit.inventory.ItemFlag;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;
public final class HalloweenShopManager implements Listener{
 private static final String TITLE=ChatColor.DARK_PURPLE+"☾ "+ChatColor.GOLD+"Halloweenský obchod";private static final int[] SLOTS={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};private final HalloweenCore plugin;private List<Offer> catalogue;
 private record Offer(Material material,int amount,int price,String name,String description,String iaId,boolean gear,boolean available){}
 private static final class Holder implements InventoryHolder{private Inventory inventory;private final Map<Integer,Offer> offers=new HashMap<>();private int page;public Inventory getInventory(){return inventory;}}
 public HalloweenShopManager(HalloweenCore p){plugin=p;catalogue=buildCatalogue();Bukkit.getPluginManager().registerEvents(this,p);}public void refresh(){catalogue=buildCatalogue();}
 public void open(CommandSender s){if(!(s instanceof Player p)){s.sendMessage(ChatColor.RED+"Obchod může otevřít jen hráč.");return;}if(!plugin.getConfig().getBoolean("shop.enabled",true)){p.sendMessage(ChatColor.RED+"Obchod je vypnutý.");return;}Holder h=new Holder();h.inventory=Bukkit.createInventory(h,54,TITLE);render(h,p);p.openInventory(h.inventory);}
 private List<Offer> buildCatalogue(){List<Offer>a=new ArrayList<>();a.add(candy("stev_apple_core","Jablečná jadérka",3));a.add(candy("stev_candy_apple","Karamelové jablko",5));a.add(candy("stev_candy_bag","Pytlík sladkostí",6));a.add(candy("stev_caramel","Karamel",3));a.add(candy("stev_caramel_apple","Jablko v karamelu",5));a.add(candy("stev_chocolate_bar","Čokoládová tyčinka",4));a.add(candy("stev_frosted_sugar_cookie","Zdobená sušenka",4));a.add(candy("stev_gumdrop","Želé bonbon",3));a.add(candy("stev_hard_candy","Tvrdý bonbon",3));a.add(candy("stev_lollipop","Lízátko",4));a.add(candy("stev_peanut_butter_cup","Arašídový košíček",4));a.add(candy("stev_sugar_cookie","Cukrová sušenka",3));a.add(candy("stev_toasted_pumpkin_seeds","Pražená dýňová semínka",3));a.add(offer(Material.IRON_INGOT,16,"iron","Železné ingoty","Balení 16 kusů.",false));a.add(offer(Material.GOLD_INGOT,8,"gold","Zlaté ingoty","Balení 8 kusů.",false));a.add(offer(Material.DIAMOND,1,"diamond","Diamant","Jeden diamant.",false));a.add(offer(Material.EMERALD,4,"emerald","Smaragdy","Balení 4 kusů.",false));a.add(offer(Material.NETHERITE_INGOT,1,"netherite-ingot","Netheritový ingot","Vzácný kov.",false));a.add(offer(Material.NETHERITE_SCRAP,2,"netherite-scrap","Netheritový šrot","Dva kusy.",false));a.add(offer(Material.GOLDEN_APPLE,1,"golden-apple","Zlaté jablko","Nouzová zásoba.",false));a.add(offer(material("ENCHANTED_GOLDEN_APPLE",Material.GOLDEN_APPLE),1,"enchanted-golden-apple","Zakleté zlaté jablko","Vzácné.",false));a.add(offer(Material.TOTEM_OF_UNDYING,1,"totem","Totem nesmrtelnosti","Velmi vzácná ochrana.",false));a.add(offer(Material.TRIDENT,1,"trident","Halloweenový trojzubec","Oranžový název a magická záře.",true));Material mace=Material.matchMaterial("MACE");a.add(new Offer(mace==null?Material.IRON_AXE:mace,1,price("mace",800),"Halloweenová Mace",mace==null?"Mace nepodporuje API serveru.":"Velmi drahá zbraň.",null,true,mace!=null));a.add(offer(Material.NETHERITE_SWORD,1,"netherite-sword","Halloweenový netheritový meč","Vzácný meč.",true));a.add(offer(Material.NETHERITE_AXE,1,"netherite-axe","Halloweenová netheritová sekera","Vzácná sekera.",true));a.add(offer(Material.NETHERITE_HELMET,1,"netherite-helmet","Halloweenová netheritová helma","Prémiová výbava.",true));a.add(offer(Material.NETHERITE_CHESTPLATE,1,"netherite-chestplate","Halloweenový netheritový hrudník","Prémiová výbava.",true));a.add(offer(Material.NETHERITE_LEGGINGS,1,"netherite-leggings","Halloweenové netheritové kalhoty","Prémiová výbava.",true));a.add(offer(Material.NETHERITE_BOOTS,1,"netherite-boots","Halloweenové netheritové boty","Prémiová výbava.",true));a.add(offer(Material.ELYTRA,1,"elytra","Halloweenová Elytra","Jedna z nejdražších položek.",true));Material spear=Material.matchMaterial("NETHERITE_SPEAR");if(spear==null)spear=Material.matchMaterial("SPEAR");a.add(new Offer(spear==null?Material.BARRIER:spear,1,price("netherite-spear",900),"Halloweenové netheritové kopí",spear==null?"API serveru kopí nepodporuje.":"Velmi vzácná halloweenská zbraň.",null,true,spear!=null));return List.copyOf(a);}
 private Offer candy(String id,String name,int fb){return new Offer(Material.COOKIE,1,price("candy",fb),name,"Sladkost z kolekce 13 textur.","warriorland_halloween:"+id,false,true);}
 private Offer offer(Material m,int n,String k,String name,String desc,boolean gear){int fb=switch(k){case "iron"->8;case "gold"->15;case "diamond"->35;case "emerald"->25;case "netherite-ingot"->150;case "netherite-scrap"->70;case "golden-apple"->18;case "enchanted-golden-apple"->80;case "totem"->350;case "trident"->550;case "mace"->800;case "netherite-sword"->400;case "netherite-axe"->350;case "netherite-helmet"->250;case "netherite-chestplate"->500;case "netherite-leggings"->400;case "netherite-boots"->200;case "elytra"->1200;case "netherite-spear"->900;default->1;};return new Offer(m,n,price(k,fb),name,desc,null,gear,true);}
 private int price(String k,int f){return Math.max(0,plugin.getConfig().getInt("shop.prices."+k,f));}private Material material(String id,Material fb){Material m=Material.matchMaterial(id);return m==null?fb:m;}
 private void render(Holder h,Player p){h.inventory.clear();h.offers.clear();for(int i=0;i<54;i++)h.inventory.setItem(i,pane(Material.BLACK_STAINED_GLASS_PANE," "));for(int i=0;i<9;i++)h.inventory.setItem(i,pane(Material.ORANGE_STAINED_GLASS_PANE," "));for(int i=45;i<54;i++)h.inventory.setItem(i,pane(Material.ORANGE_STAINED_GLASS_PANE," "));h.inventory.setItem(4,named(Material.JACK_O_LANTERN,ChatColor.GOLD+"☾ Halloweenský obchod",List.of(ChatColor.GRAY+"Platíš Halloween fragmenty.",ChatColor.DARK_GRAY+"Klikni na předmět pro nákup."),false));h.inventory.setItem(46,named(Material.AMETHYST_SHARD,ChatColor.LIGHT_PURPLE+"Fragmenty: "+plugin.getQuestManager().getFragments(p.getUniqueId()),List.of(ChatColor.GRAY+"Úkol získáš přes /quest."),false));h.inventory.setItem(49,named(Material.BARRIER,ChatColor.RED+"Zavřít obchod",List.of(),false));if(h.page>0)h.inventory.setItem(45,named(Material.ARROW,ChatColor.YELLOW+"Předchozí stránka",List.of(),false));if((h.page+1)*SLOTS.length<catalogue.size())h.inventory.setItem(53,named(Material.ARROW,ChatColor.YELLOW+"Další stránka",List.of(),false));h.inventory.setItem(51,named(Material.SOUL_LANTERN,ChatColor.DARK_PURPLE+"Výbava lovce",List.of(ChatColor.GRAY+"Mace, trojzubec a Elytra.",ChatColor.GRAY+"Stojí nejvíc fragmentů."),false));for(int i=0;i<SLOTS.length;i++){int ix=h.page*SLOTS.length+i;if(ix>=catalogue.size())break;int slot=SLOTS[i];Offer o=catalogue.get(ix);List<String> lore=new ArrayList<>();lore.add(ChatColor.GRAY+o.description());if(o.available()){lore.add(ChatColor.DARK_GRAY+"Cena: "+ChatColor.GOLD+o.price()+" fragmentů");lore.add(ChatColor.YELLOW+"Klikni pro nákup");}else lore.add(ChatColor.RED+"Není dostupné v této verzi serveru");h.inventory.setItem(slot,named(o.material(),(o.gear()?ChatColor.GOLD.toString()+ChatColor.BOLD:ChatColor.GOLD)+o.name(),lore,o.gear()));if(o.available())h.offers.put(slot,o);}h.inventory.setItem(48,named(Material.PUMPKIN,ChatColor.GOLD+"Sladkosti & poklady",List.of(ChatColor.GRAY+"Suroviny a vzácná výbava."),false));}
 @EventHandler public void onClick(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof Holder h))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;int s=e.getRawSlot();if(s<0||s>=e.getView().getTopInventory().getSize())return;if(s==49){p.closeInventory();return;}if(s==45&&h.page>0){h.page--;render(h,p);return;}if(s==53&&(h.page+1)*SLOTS.length<catalogue.size()){h.page++;render(h,p);return;}Offer o=h.offers.get(s);if(o!=null)purchase(p,o,h);}
 @EventHandler public void onDrag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Holder)e.setCancelled(true);}
 private ItemStack buildItem(Offer o){if(o.iaId()!=null&&Bukkit.getPluginManager().isPluginEnabled("ItemsAdder"))try{Class<?> c=Class.forName("dev.lone.itemsadder.api.CustomStack");Object custom=c.getMethod("getInstance",String.class).invoke(null,o.iaId());if(custom!=null){Object raw=c.getMethod("getItemStack").invoke(custom);if(raw instanceof ItemStack stack)return stack;}}catch(ReflectiveOperationException ex){plugin.getLogger().fine("ItemsAdder item není dostupný: "+o.iaId());}ItemStack item=new ItemStack(o.material(),o.amount());ItemMeta meta=item.getItemMeta();if(meta!=null){meta.setDisplayName(ChatColor.GOLD+o.name());meta.setLore(List.of(ChatColor.GRAY+o.description(),ChatColor.DARK_GRAY+"Halloweenský obchod"));item.setItemMeta(meta);}return item;}
 private void purchase(Player p,Offer o,Holder h){long bal=plugin.getQuestManager().getFragments(p.getUniqueId());if(bal<o.price()){p.sendMessage(ChatColor.RED+"Nemáš dost fragmentů. Cena "+o.price()+", máš "+bal+".");return;}if(p.getInventory().firstEmpty()==-1){p.sendMessage(ChatColor.RED+"Udělej si místo v inventáři.");return;}ItemStack item=buildItem(o);ItemMeta meta=item.getItemMeta();if(meta!=null&&o.gear()){meta.setDisplayName(ChatColor.GOLD.toString()+ChatColor.BOLD+o.name());meta.setLore(List.of(ChatColor.GRAY+o.description(),ChatColor.DARK_GRAY+"Halloweenský obchod"));item.setItemMeta(meta);item.addUnsafeEnchantment(Enchantment.UNBREAKING,1);}Map<Integer,ItemStack> extra=p.getInventory().addItem(item);for(ItemStack it:extra.values())p.getWorld().dropItemNaturally(p.getLocation(),it);plugin.getPlayerData().set("players."+p.getUniqueId()+".fragments",bal-o.price());plugin.savePlayerData();p.sendMessage(ChatColor.GREEN+"Koupeno: "+ChatColor.GOLD+o.name()+ChatColor.GRAY+" za "+ChatColor.YELLOW+o.price()+" fragmentů.");render(h,p);}
 private ItemStack pane(Material m,String n){return named(m,n,List.of(),false);}private ItemStack named(Material m,String n,List<String> lore,boolean glow){ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();if(meta!=null){meta.setDisplayName(n);meta.setLore(lore);if(glow)meta.addItemFlags(ItemFlag.HIDE_ENCHANTS);i.setItemMeta(meta);}if(glow)i.addUnsafeEnchantment(Enchantment.UNBREAKING,1);return i;}
}
